# All 24 words and the 12 A-before-B words are literal, not generated by production code.
WORDS4 = 'ABCD ABDC ACBD ACDB ADBC ADCB BACD BADC BCAD BCDA BDAC BDCA CABD CADB CBAD CBDA CDAB CDBA DABC DACB DBAC DBCA DCAB DCBA'.split()
WIN4 = set('ABCD ABDC ACBD ACDB ADBC ADCB CABD CADB CDAB DABC DACB DCAB'.split())


def simple_problem(n):
    names = list('ABCDEFG'[:n])
    source = 'Synthetic declared-slot acceptance fixture.'
    return {'schema_version': 'ce3-scenario-problem/2', 'revision': 1,
            'purpose': 'synthetic_integration_test', 'profile': 'fixed-replay/0.1',
            'model': {'schema_version': 'ce3-model/1', 'source': source,
                      'clock': {'start': 0, 'horizon': max(n - 1, 0), 'step': 1, 'unit': 'test_step',
                                'events_before_decisions': True, 'horizon_inclusive': True},
                      'domains': {k.lower(): {'enum': [False, True]} for k in names},
                      'initial': {k.lower(): False for k in names}, 'budget': None,
                      'decisions': {k: {'requires': [], 'effects': {'set': {k.lower(): True}, 'add': {}},
                                        'cost': 0, 'schedule': None, 'source': source} for k in names},
                      'events': {}, 'initial_events': [], 'reference_event_order': [],
                      'metadata': {'assumption': source, 'time_basis': 'Declared unit steps, inclusive horizon.',
                                   'deadlines': []}},
            'sources': {}, 'search': {'kind': 'permutations_once/2', 'decision_ids': names,
                                     'slots': list(range(n)), 'mode': 'attempt', 'retry': False, 'early_stop': False},
            'observation': {'schema_version': 'ce3-terminal-goal/1', 'goal_id': 'terminal',
                            'sampling': 'last_row.after', 'quantifier': 'all_event_paths',
                            'terminal_equals': {k.lower(): True for k in names}, 'all_attempts_accepted': True},
            'scenario_set': {'schema_version': 'ce3-scenario-set/1', 'variation': 'outcomes_only',
                             'selection': 'explicit_complete_list', 'members': [{'label': 'only', 'outcomes': {}}]}}


def timer_problem():
    p = simple_problem(2)
    p['search']['slots'] = [2, 6]
    m = p['model']
    m['clock'].update(start=1, horizon=10)
    m['domains']['ready'] = {'enum': [False, True]}
    m['initial']['ready'] = False
    m['decisions']['A']['schedule'] = {'event': 'ready', 'delay': 4}
    m['decisions']['B']['requires'] = [{'field': 'ready', 'op': 'eq', 'value': True}]
    m['events']['ready'] = {'requires': [], 'kind': 'timer', 'outcomes': {'set': {'set': {'ready': True}, 'add': {}}},
                            'absent': None, 'source': 'A schedules readiness four steps later.'}
    m['reference_event_order'] = ['ready']
    p['observation']['terminal_equals'] = {'ready': True}  # BA still fails accepted-attempts condition
    return p


def crossing_problem():
    p = simple_problem(4)
    p['search']['slots'] = [-2, 1, 4, 7]
    m = p['model']
    m['clock'].update(start=-3, horizon=9)
    m['decisions']['B']['requires'] = [{'field': 'a', 'op': 'eq', 'value': True}]
    m['domains'].update(response={'enum': ['waiting', 'approved', 'rejected']}, late={'enum': [False, True]})
    m['initial'].update(response='waiting', late=False)
    m['events'] = {
        'response': {'requires': [], 'kind': 'external',
                     'outcomes': {k: {'set': {'response': v}, 'add': {}}
                                  for k, v in [('yes', 'approved'), ('no', 'rejected'), ('absent', 'waiting')]},
                     'absent': {'outcome': 'absent', 'field': 'response', 'value': 'waiting', 'source': 'Explicit waiting branch.'},
                     'source': 'External response at step zero.'},
        'finish': {'requires': [], 'kind': 'timer', 'outcomes': {'done': {'set': {'late': True}, 'add': {}}},
                   'absent': None, 'source': 'D schedules finish two steps later.'}}
    m['decisions']['D']['schedule'] = {'event': 'finish', 'delay': 2}
    m['initial_events'] = [{'id': 'response', 'due': 0, 'scheduled_at': -3}]
    m['reference_event_order'] = ['response', 'finish']
    p['observation']['terminal_equals'].update(response='approved', late=True)
    p['scenario_set']['members'] = [{'label': k, 'outcomes': {'response': k}} for k in ('yes', 'no', 'absent')]
    return p


class FixedSlots(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temp = tempfile.TemporaryDirectory(prefix='ce3-slots-tests-')
        cls.problem = read_bundle(ROOT / 'fixtures/slots-problem.json')
        cls.manifest, cls.pins = contracts.freeze(cls.problem)
        cls.complete = Path(cls.temp.name) / 'complete'
        with patch.object(runner, 'cli_process', wraps=runner.cli_process) as calls:
            cls.result = runner.run(cls.problem, cls.manifest, cls.pins, cls.complete)
            cls.commands = [c.args[0] for c in calls.call_args_list]

    @classmethod
    def tearDownClass(cls):
        cls.temp.cleanup()

    def setUp(self):
        self.work = Path(self.temp.name) / self.id().split('.')[-1]

    def execute(self, p, suffix='', **kwargs):
        m, pins = contracts.freeze(p)
        path = self.work / (suffix or 'run')
        return runner.run(p, m, pins, path, **kwargs), path, pins

    def clone(self, suffix='copy'):
        path = self.work / suffix
        shutil.copytree(self.complete, path)
        return path

    def assert_unknown(self, cell):
        self.assertIsNone(cell['goal_satisfied'])
        self.assertEqual(cell['goal_status'], 'UNKNOWN')
        self.assertEqual(cell['event_path_coverage'], {'status': 'UNKNOWN', 'audited_paths': None})

    def test_four_decisions_three_scenarios_literal_24_72(self):
        self.assertEqual(self.problem, crossing_problem())
        self.assertEqual(self.commands, ['replay', 'audit'] * 72)
        self.assertEqual([''.join(c['order']) for c in self.manifest['candidates']], WORDS4)
        self.assertEqual(len(self.result['cells']), 72)
        self.assertEqual(len({c['cell_id'] for c in self.result['cells']}), 72)
        self.assertEqual(self.manifest, read_bundle(ROOT / 'fixtures/slots-manifest.json'))
        self.assertEqual(self.pins, read_bundle(ROOT / 'fixtures/slots-pins.json'))
        for c in self.result['cells']:
            self.assertEqual(c['run_status'], 'CERTIFIED')
            self.assertEqual(c['goal_satisfied'], ''.join(c['order']) in WIN4 and c['scenario_label'] == 'yes')
            # D at -2 schedules finish at 0, simultaneous with the external response.
            # They affect disjoint fields: both orders have the same goal verdict.
            self.assertEqual(c['event_path_coverage'],
                             {'status': 'COMPLETE', 'audited_paths': 2 if c['order'][0] == 'D' else 1})
        self.assertEqual(sum(c['event_path_coverage']['audited_paths'] for c in self.result['cells']), 90)
        self.assertEqual(sum(c['goal_satisfied'] for c in self.result['cells']), 12)
        self.assertEqual({c['robust'] for c in self.result['candidates']}, {'FALSE'})
        for key in ('candidate_coverage', 'scenario_coverage', 'cell_coverage', 'enumeration_coverage'):
            self.assertEqual(self.result[key]['status'], 'COMPLETE')

    def test_direct_full_input_oracle_and_post_last_slot_timer(self):
        for c in self.result['cells']:
            a, b, d, e = c['order']
            expected = {'schema_version': 'ce3-run/1', 'profile': 'fixed-replay/0.1',
                        'model': self.problem['model'], 'sources': {},
                        'outcomes': {'response': c['scenario_label']},
                        'script': {'schema_version': 'ce3-script/1', 'source': SCRIPT_SOURCE,
                                   'steps': {'-2': [{'decision': a, 'mode': 'attempt'}],
                                             '1': [{'decision': b, 'mode': 'attempt'}],
                                             '4': [{'decision': d, 'mode': 'attempt'}],
                                             '7': [{'decision': e, 'mode': 'attempt'}]}}}
            directory = self.complete / 'runs' / c['cell_id']
            self.assertEqual(read_bundle(directory / 'input.json'), expected)
            self.assertEqual(c['input_identity'], digest(expected))
            bundle = read_bundle(directory / 'history.json.gz')
            rows = bundle['paths'][0]['history']
            self.assertEqual(rows[-1]['step'], 9)
            self.assertTrue(rows[-1]['after']['state']['late'])
            if c['order'][-1] == 'D':
                self.assertEqual([r['step'] for r in rows if r['action'] == 'finish' and r['kind'] == 'event_applied'], [9])

    def test_minimum_one_decision_single_slot_negative_clock(self):
        p = simple_problem(1)
        p['search']['slots'] = [-4]
        p['model']['clock'].update(start=-4, horizon=-4)
        r, root, pins = self.execute(p)
        self.assertEqual(len(r['cells']), 1)
        self.assertEqual(r['candidates'][0]['robust'], 'TRUE')
        self.assertEqual(r['cell_coverage']['status'], 'COMPLETE')
        self.assertEqual(runner.verify(root, pins), r)
        inp = read_bundle(root / 'runs' / r['cells'][0]['cell_id'] / 'input.json')
        self.assertEqual(inp['script']['steps'], {'-4': [{'decision': 'A', 'mode': 'attempt'}]})

    def test_two_permutations_gaps_events_before_decisions_and_late_horizon(self):
        r, root, _ = self.execute(timer_problem())
        self.assertEqual({tuple(c['order']) for c in r['cells']}, {('A', 'B'), ('B', 'A')})
        for c in r['cells']:
            first = c['order'] == ['A', 'B']
            self.assertEqual(c['goal_satisfied'], first)
            directory = root / 'runs' / c['cell_id']
            obs = read_bundle(directory / 'observation.json')['projection']['paths'][0]
            self.assertEqual(obs['terminal_state']['ready'], True)
            self.assertEqual(obs['all_attempts_accepted'], first)
            rows = read_bundle(directory / 'history.json.gz')['paths'][0]['history']
            events = [row for row in rows if row['kind'] == 'event_applied']
            self.assertEqual([row['step'] for row in events], [6 if first else 10])
            if first:
                self.assertLess(events[0]['index'], next(row['index'] for row in rows if row['kind'] == 'decision_executed' and row['action'] == 'B'))
            inp = read_bundle(directory / 'input.json')
            self.assertEqual(inp['script']['steps'], {'2': [{'decision': c['order'][0], 'mode': 'attempt'}],
                                                     '6': [{'decision': c['order'][1], 'mode': 'attempt'}]})

    def test_horizon_does_not_force_pending_events_to_execute(self):
        p = timer_problem()
        p['model']['clock']['horizon'] = 9
        r, root, _ = self.execute(p)
        c = next(c for c in r['cells'] if c['order'] == ['B', 'A'])
        obs = read_bundle(root / 'runs' / c['cell_id'] / 'observation.json')['projection']['paths'][0]
        self.assertFalse(obs['terminal_state']['ready'])
        self.assertEqual([(e['id'], e['due']) for e in obs['pending']], [('ready', 10)])

    def test_five_120_independent_population_no_cartesian_or_generator(self):
        p = simple_problem(5)
        with patch.object(contracts, 'permutations', side_effect=AssertionError('generator used')), \
             patch.object(contracts, 'product', side_effect=AssertionError('cartesian used')), \
             patch.object(contracts, 'generate', side_effect=AssertionError('generator used')):
            m, pins = contracts.freeze(p)
            self.assertEqual(len(m['candidates']), 120)
            self.assertEqual(len({tuple(c['order']) for c in m['candidates']}), 120)
            for c in m['candidates']:
                self.assertEqual(sorted(c['order']), list('ABCDE'))
            # 120 distinct length-five permutations exhaust the mathematically known 5! universe.
            contracts.verify_frozen(p, m, pins)
        with patch.object(contracts, 'expected_orders', side_effect=AssertionError('oracle used')):
            generated = contracts.generate(p)
        self.assertEqual(contracts.check_population(m, generated)['status'], 'COMPLETE')

    def test_identifier_and_input_order_invariance(self):
        p = deepcopy(self.problem)
        names = {'A': 'z', 'B': 'ä', 'C': 'm', 'D': 'a'}
        reverse = {v: k for k, v in names.items()}
        p['model']['decisions'] = {names[k]: v for k, v in reversed(list(p['model']['decisions'].items()))}
        p['search']['decision_ids'] = [names[k] for k in 'DCBA']  # deliberately not sorted
        p['scenario_set']['members'].reverse()
        r, _, _ = self.execute(p)
        for c in r['cells']:
            word = ''.join(reverse[k] for k in c['order'])
            self.assertEqual(c['goal_satisfied'], word in WIN4 and c['scenario_label'] == 'yes')
        self.assertEqual(r['cell_coverage']['status'], 'COMPLETE')

    def test_invalid_declarations_fail_before_replay(self):
        mutations = [(['search', 'slots'], x) for x in ([], [2], [2, 2], [6, 2], [True, 6], [2.0, 6], ['2', 6], [0, 6], [2, 11])]
        mutations += [(['model', 'clock', 'horizon'], x) for x in (5, 0, True, 10.0, '10')]
        mutations += [(['search', 'decision_ids'], x) for x in ([], ['A', 'A'], ['', 'B'], ['A', 'missing'])]
        mutations += [(['search', 'kind'], 'permutations_once/1'), (['search', 'retry'], True),
                      (['search', 'early_stop'], True), (['search', 'mode'], 'if_not_taken'),
                      (['model', 'clock', 'step'], 2), (['schema_version'], 'ce3-scenario-problem/3')]
        for keys, value in mutations:
            p = timer_problem()
            target = p
            for key in keys[:-1]: target = target[key]
            target[keys[-1]] = value
            with self.subTest(keys=keys, value=value), patch.object(runner, 'cli_process') as cli:
                with self.assertRaises(ValueError): contracts.freeze(p)
                cli.assert_not_called()
        for key in ('model', 'search', 'script', 'observation', 'clock'):
            p = timer_problem()
            p['scenario_set']['members'][0][key] = {}
            with self.assertRaises(ValueError): contracts.freeze(p)

    def test_size_bounds_checked_before_any_population_or_input_copy(self):
        for p in (simple_problem(7), dict(simple_problem(1), scenario_set=dict(simple_problem(1)['scenario_set'],
                                      members=[{'label': str(i), 'outcomes': {}} for i in range(2161)]))):
            with patch.object(contracts, 'candidate', side_effect=AssertionError('candidate materialized')), \
                 patch.object(contracts, 'effective_problem', side_effect=AssertionError('input copied')), \
                 patch.object(contracts, 'product', side_effect=AssertionError('cartesian enumerated')), \
                 patch.object(contracts, 'permutations', side_effect=AssertionError('enumerated')), \
                 patch.object(contracts, 'expected_orders', side_effect=AssertionError('oracle enumerated')):
                for operation in (contracts.freeze, contracts.generate, runner.preflight):
                    with self.assertRaisesRegex(ValueError, 'Unsupported search size'): operation(p)
                with self.assertRaisesRegex(ValueError, 'Unsupported search size'):
                    runner.run(p, {}, {}, self.work, max_cells=0)
        self.assertFalse(self.work.exists())
        p = simple_problem(6)
        p['scenario_set']['members'] = [{'label': str(i), 'outcomes': {}} for i in range(3)]
        self.assertEqual(runner.preflight(p)['search_size']['cell_count'], 2160)
        self.assertEqual(runner.preflight(p)['search_size']['candidate_count'], 720)
        p['scenario_set']['members'].append({'label': 'fourth', 'outcomes': {}})
        with self.assertRaisesRegex(ValueError, '2880 cells'): runner.preflight(p)
        # Same cell boundary at the smallest n.
        p = simple_problem(1)
        p['scenario_set']['members'] = [{'label': str(i), 'outcomes': {}} for i in range(2160)]
        self.assertEqual(fixed_slots.search_size(p)['cell_count'], 2160)

    def test_budget_preserves_population_and_three_valued_robustness(self):
        for budget in (0, 1, 2, 4):
            r, root, pins = self.execute(self.problem, str(budget), max_cells=budget)
            self.assertEqual(r['cell_coverage']['expected'], 72)
            self.assertEqual(r['cell_coverage']['certified'], budget)
            self.assertEqual(r['cell_coverage']['status'], 'INCOMPLETE')
            self.assertEqual(r['enumeration_coverage']['status'], 'COMPLETE')
            self.assertEqual(len(read_bundle(root / 'enumeration.json')), 72)
            self.assertEqual(runner.verify(root, pins), r)
            for c in r['cells']:
                if c['run_status'] == 'NOT_RUN': self.assert_unknown(c)
            states = {''.join(c['order']): c['robust'] for c in r['candidates']}
            self.assertEqual(states['ABCD'], 'FALSE' if budget >= 2 else 'UNKNOWN')
            self.assertEqual(states['ABDC'], 'UNKNOWN')
            self.assertNotIn('TRUE', states.values())

