    def test_enumeration_damage_cannot_be_repaired_by_complete_projections(self):
        for mode in ('missing', 'duplicate', 'unexpected', 'misbound'):
            root = self.clone(mode)
            cells = deepcopy(self.manifest['cells'])
            if mode == 'missing': cells.pop()
            elif mode == 'duplicate': cells[-1] = cells[0]
            elif mode == 'unexpected': cells[-1]['cell_id'] = '0' * 64
            else: cells[-1]['candidate_id'] = '0' * 64
            write_bundle(cells, root / 'enumeration.json')
            r = runner.verify(root, self.pins)
            self.assertEqual(r['cell_coverage']['status'], 'INCOMPLETE' if mode == 'missing' else 'INVALID')
            self.assertEqual(r['cell_coverage']['certified'], 72)
            self.assertEqual(r['candidate_coverage']['status'], 'COMPLETE')
            self.assertEqual(r['scenario_coverage']['status'], 'COMPLETE')

    def test_missing_duplicate_unexpected_misbound_candidates_and_cells(self):
        for field in ('candidates', 'cells'):
            for kind in ('missing', 'duplicate', 'unexpected', 'misbound'):
                m = deepcopy(self.manifest)
                rows = m[field]
                if kind == 'missing': rows.pop()
                elif kind == 'duplicate': rows[-1] = rows[0]
                elif kind == 'unexpected': rows[-1]['candidate_id' if field == 'candidates' else 'cell_id'] = '0' * 64
                else: rows[-1]['plan_id'] = '0' * 64
                pins = dict(self.pins, manifest_id=digest(m))
                with self.subTest(field=field, kind=kind), self.assertRaises(ValueError):
                    contracts.verify_frozen(self.problem, m, pins)
                if field == 'cells':
                    self.assertEqual(contracts.check_population(self.manifest, rows)['status'],
                                     'INCOMPLETE' if kind == 'missing' else 'INVALID')

    def test_generator_omission_stops_before_any_run(self):
        with patch.object(runner, 'generate', return_value=self.manifest['cells'][:-1]), \
             patch.object(runner, 'cli_process') as cli:
            with self.assertRaisesRegex(ValueError, 'Generator coverage'):
                runner.run(self.problem, self.manifest, self.pins, self.work)
            cli.assert_not_called()
        self.assertFalse(self.work.exists())

    def test_consistently_rehashed_candidate_or_cell_omission(self):
        for mode in ('candidate', 'cell'):
            root = self.clone(mode)
            m = deepcopy(self.manifest)
            removed = ({c['cell_id'] for c in m['cells'] if c['candidate_id'] == m['candidates'][-1]['candidate_id']}
                       if mode == 'candidate' else {m['cells'][-1]['cell_id']})
            if mode == 'candidate': m['candidates'].pop()
            m['cells'] = [c for c in m['cells'] if c['cell_id'] not in removed]
            m['search_size'].update(candidate_count=len(m['candidates']), cell_count=len(m['cells']))
            pins = dict(self.pins, manifest_id=digest(m))
            spec = read_bundle(root / 'batch.json')
            spec.update(manifest_id=digest(m), max_cells=len(m['cells']), search_size=m['search_size'])
            attempt = read_bundle(root / 'attempt.json')
            attempt['batch_spec_id'] = digest(spec)
            result = deepcopy(self.result)
            result['cells'] = [c for c in result['cells'] if c['cell_id'] not in removed]
            result['candidates'] = [c for c in result['candidates'] if c['candidate_id'] in {p['candidate_id'] for p in m['candidates']}]
            result.update(manifest_id=digest(m), batch_spec_id=digest(spec),
                          enumeration_coverage=contracts.check_population(m, m['cells']))
            result['preflight'].update(search_size=m['search_size'], max_cells=len(m['cells']))
            result['cell_coverage'].update(expected=len(m['cells']), certified=len(m['cells']))
            result['candidate_coverage'].update(expected=len(m['candidates']), certified_represented=len(m['candidates']))
            for c in result['candidates']:
                group = [r for r in result['cells'] if r['candidate_id'] == c['candidate_id']]
                c.update(cell_ids=[r['cell_id'] for r in group], expected_scenarios=len(group), certified_cells=len(group), robust=runner.robust(group))
            for c in m['cells']:
                directory = root / 'runs' / c['cell_id']
                rec = read_bundle(directory / 'record.json')
                base = runner.base_record(c, spec, attempt['batch_attempt_id'], rec['run_id'])
                obs = read_bundle(directory / 'observation.json')
                obs['batch_spec_id'] = digest(spec)
                rec.update(base, observation_id=digest(obs))
                next(row for row in result['cells'] if row['cell_id'] == c['cell_id'])['observation_id'] = digest(obs)
                for name, value in (('started', base), ('record', rec), ('observation', obs)):
                    write_bundle(value, directory / (name + '.json'))
            for key in removed: shutil.rmtree(root / 'runs' / key)
            result.pop('result_id')
            result['result_id'] = digest(result)
            for name, value in (('manifest', m), ('pins', pins), ('batch', spec), ('attempt', attempt),
                                ('enumeration', m['cells']), ('result', result)):
                write_bundle(value, root / (name + '.json'))
            self.assertEqual(contracts.check_population(m, m['cells'])['status'], 'COMPLETE')
            with self.assertRaisesRegex(ValueError, 'Trusted problem/manifest identity mismatch'):
                runner.verify(root, pins)

    def test_corrupt_gzip_audit_failure_and_artifact_swap_are_unknown(self):
        target = next(c for c in self.result['cells'] if c['goal_satisfied'])
        for mode in ('truncated', 'deflate', 'audit', 'swap'):
            root = self.clone(mode)
            directory = root / 'runs' / target['cell_id']
            history = directory / 'history.json.gz'
            if mode == 'truncated': history.write_bytes(history.read_bytes()[:-8])
            elif mode == 'deflate':
                data = bytearray(history.read_bytes()); data[10] = (data[10] & 0xf8) | 7; history.write_bytes(data)
            elif mode == 'audit': write_bundle({'status': 'FAIL'}, directory / 'audit.json')
            else:
                other = next(c for c in self.result['cells'] if c['candidate_id'] == target['candidate_id'] and c['cell_id'] != target['cell_id'])
                shutil.copyfile(root / 'runs' / other['cell_id'] / 'input.json', directory / 'input.json')
            # Refresh physical artifact hashes so a stale checksum is not the only defense.
            rec = read_bundle(directory / 'record.json')
            from bridge import file_hash
            for name in rec['artifact_hashes']: rec['artifact_hashes'][name] = file_hash(directory / name)
            write_bundle(rec, directory / 'record.json')
            old_result = (root / 'result.json').read_bytes()
            r = runner.verify(root, self.pins)
            self.assertEqual(r['cell_coverage']['certified'], 71)
            self.assertEqual(r['cell_coverage']['status'], 'INCOMPLETE')
            self.assert_unknown(next(c for c in r['cells'] if c['cell_id'] == target['cell_id']))
            self.assertEqual((root / 'result.json').read_bytes(), old_result)

    def test_all_event_paths_and_rehashed_removed_negative_path(self):
        p = timer_problem()
        m = p['model']
        m['events']['clear'] = {'requires': [], 'kind': 'timer', 'outcomes': {'clear': {'set': {'ready': False}, 'add': {}}},
                                'absent': None, 'source': 'Competing clear at step 6.'}
        m['initial_events'] = [{'id': 'clear', 'due': 6, 'scheduled_at': 1}]
        m['reference_event_order'] = ['clear', 'ready']
        r, root, pins = self.execute(p)
        c = next(c for c in r['cells'] if c['order'] == ['A', 'B'])
        self.assertFalse(c['goal_satisfied'])
        self.assertEqual(c['event_path_coverage']['audited_paths'], 2)
        directory = root / 'runs' / c['cell_id']
        obs = read_bundle(directory / 'observation.json')['projection']
        self.assertEqual([path['goal_satisfied'] for path in obs['paths']], [True, False])
        bundle = read_bundle(directory / 'history.json.gz')
        bundle['paths'] = bundle['paths'][:1]
        write_bundle(bundle, directory / 'history.json.gz')
        rec = read_bundle(directory / 'record.json')
        rec = runner.artifact_record(rec, directory)
        write_bundle(rec, directory / 'record.json')
        result = runner.verify(root, pins)
        bad = next(row for row in result['cells'] if row['cell_id'] == c['cell_id'])
        self.assert_unknown(bad)
        self.assertIn('Incomplete permutation coverage', bad['reason'])
        self.assertEqual(next(row['robust'] for row in result['candidates'] if row['order'] == ['A', 'B']), 'UNKNOWN')
        limited, _, _ = self.execute(p, 'limited', limits=dict(LIMITS, max_paths=1))
        self.assert_unknown(next(row for row in limited['cells'] if row['order'] == ['A', 'B']))

    def test_replay_limits_keep_unknown_goals(self):
        for key in ('max_steps', 'max_rows'):
            r, _, _ = self.execute(timer_problem(), key, limits=dict(LIMITS, **{key: 1}))
            self.assertEqual(r['cell_coverage']['certified'], 0)
            for c in r['cells']: self.assert_unknown(c)
            self.assertEqual({c['robust'] for c in r['candidates']}, {'UNKNOWN'})

    def test_cli_preflight_full_partial_and_oversize(self):
        def cli(*args):
            return subprocess.run([sys.executable, '-B', str(ROOT / 'scenario_runner.py'), *map(str, args)],
                                  capture_output=True, text=True)
        out = cli('preflight', '--problem', ROOT / 'fixtures/slots-problem.json', '--max-cells', 2)
        self.assertEqual(out.returncode, 0, out.stderr)
        self.assertIn("'candidate_count': 24", out.stdout)
        self.assertIn("'cell_count': 72", out.stdout)
        self.assertIn("'max_cells': 2", out.stdout)
        self.assertIn("'process_timeout_seconds': 60", out.stdout)
        out = cli('verify', '--output', self.complete, '--pins', ROOT / 'fixtures/slots-pins.json')
        self.assertEqual(out.returncode, 0, out.stderr)
        root = self.work / 'partial'
        out = cli('run', '--problem', ROOT / 'fixtures/slots-problem.json', '--manifest', ROOT / 'fixtures/slots-manifest.json',
                  '--pins', ROOT / 'fixtures/slots-pins.json', '--max-cells', 0, '--output', root)
        self.assertEqual(out.returncode, 2, out.stderr)
        out = cli('verify', '--pins', ROOT / 'fixtures/slots-pins.json', '--output', root)
        self.assertEqual(out.returncode, 2, out.stderr)
        write_bundle(simple_problem(7), self.work / 'oversize.json')
        out = cli('freeze', '--problem', self.work / 'oversize.json', '--output', self.work / 'forbidden')
        self.assertEqual(out.returncode, 1, out.stderr)
        self.assertIn('Unsupported search size', out.stderr)
        self.assertFalse((self.work / 'forbidden').exists())

    def test_old_contracts_fixtures_and_version_separation(self):
        p = read_bundle(ROOT / 'fixtures/problem.json')
        self.assertEqual(legacy.freeze(p), (read_bundle(ROOT / 'fixtures/search-manifest.json'), read_bundle(ROOT / 'fixtures/pins.json')))
        p = read_bundle(ROOT / 'fixtures/scenario-problem.json')
        self.assertEqual(contracts.freeze(p), (read_bundle(ROOT / 'fixtures/scenario-manifest.json'), read_bundle(ROOT / 'fixtures/scenario-pins.json')))
        for version in ('ce3-scenario-problem/1', 'ce3-explorer-problem/1'):
            p = timer_problem()
            p['schema_version'] = version
            with self.assertRaises(ValueError): contracts.freeze(p)
        p = timer_problem()
        with self.assertRaises(ValueError): legacy.freeze(contracts.effective_problem(p, p['scenario_set']['members'][0]))
        self.assertEqual(self.result['schema_version'], 'ce3-scenario-result/2')
        self.assertEqual(self.manifest['schema_version'], 'ce3-scenario-manifest/2')


